riant":"nlh","bigBlindAnte":true,"payoutPreset":"NINE","startingStack":10000,"addOnAvailable":true,"guaranteedPrize":500,"horsesToRegister":0,"shortDescription":"Rebuys Cost 5 Chips And Receive The Starting Stack. One 5 Chip Add-On At Late-Reg Close Receives 2x Starting Stack.","lateRegistrationLevels":7,"rebuyLevels":7,"addonLevels":1,"addonFromStart":false,"addonBreakMinutes":5},"patch":{"starting_chips":10000,"late_reg_levels":7,"late_reg_mins":56,"is_rebuy":true,"is_reentry":true,"rebuy_chips":10000,"rebuy_levels":7,"addon_chips":20000,"addon_levels":1,"addon_from_start":false,"addon_break_minutes":5,"big_blind_ante":true,"guaranteed_prize":500,"blind_speed":"standard","is_turbo":false,"profile":"nlh-8"}}]$definitions$::jsonb;
  item jsonb; patch jsonb; cfg jsonb; structure jsonb; current_cfg jsonb;
  v_schedule_id uuid; changed integer := 0;
BEGIN
  IF public.fn_platform_frozen() THEN RAISE EXCEPTION 'Midway configuration waits for platform thaw'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(definitions) LOOP
    v_schedule_id := (item->>'id')::uuid;
    patch := item->'patch';
    structure := profiles->(patch->>'profile');
    cfg := (item->'config') || jsonb_build_object('blindStructure',structure);
    SELECT s.config INTO current_cfg FROM public.tournament_schedules s
     WHERE s.id=v_schedule_id AND s.active
       AND (s.club_id='fade0000-0000-0000-0000-000000000001'::uuid
         OR s.union_id='fade0000-0000-0000-0000-000000000001'::uuid)
     FOR UPDATE;
    IF NOT FOUND OR (current_cfg IS DISTINCT FROM item->'before' AND current_cfg IS DISTINCT FROM cfg) THEN
      RAISE EXCEPTION 'Midway schedule % drifted; review current configuration before installation',v_schedule_id;
    END IF;
    UPDATE public.tournament_schedules s SET config=cfg,updated_at=now()
     WHERE s.id=v_schedule_id AND s.config IS DISTINCT FROM cfg;
    -- Registration owns a row lock and changes entry_contract_locked/count.
    -- Recheck both flags plus actual entrants under this same write lock.
    UPDATE public.tournaments t SET
      starting_chips=(patch->>'starting_chips')::integer,
      blind_structure=structure::text,
      blind_speed=patch->>'blind_speed',is_turbo=(patch->>'is_turbo')::boolean,
      late_reg_levels=(patch->>'late_reg_levels')::integer,
      late_reg_mins=(patch->>'late_reg_mins')::integer,
      rebuy_chips=(patch->>'rebuy_chips')::integer,
      rebuy_levels=(patch->>'rebuy_levels')::integer,
      addon_chips=(patch->>'addon_chips')::integer,
      addon_levels=(patch->>'addon_levels')::integer,
      addon_from_start=(patch->>'addon_from_start')::boolean,
      addon_break_minutes=COALESCE((patch->>'addon_break_minutes')::integer,t.addon_break_minutes),
      big_blind_ante=(patch->>'big_blind_ante')::boolean,
      guaranteed_prize=(patch->>'guaranteed_prize')::numeric,
      updated_at=now()
    WHERE t.schedule_id=v_schedule_id
      AND (t.club_id='fade0000-0000-0000-0000-000000000001'::uuid
        OR t.union_id='fade0000-0000-0000-0000-000000000001'::uuid)
      AND t.status IN ('ANNOUNCED','REGISTERING') AND t.start_time>now()
      AND NOT COALESCE(t.entry_contract_locked,false)
      AND NOT COALESCE(t.prize_pool_finalized,false)
      AND COALESCE(t.current_players,0)=0
      AND NOT EXISTS(SELECT 1 FROM public.tournament_players p WHERE p.tournament_id=t.id)
      AND ROW(t.starting_chips,t.blind_structure::jsonb,t.guaranteed_prize,t.late_reg_levels,t.late_reg_mins,t.rebuy_chips,t.rebuy_levels,t.addon_chips,t.addon_levels,t.addon_from_start,t.addon_break_minutes,t.big_blind_ante)
        IS DISTINCT FROM ROW((patch->>'starting_chips')::integer,structure,(patch->>'guaranteed_prize')::numeric,(patch->>'late_reg_levels')::integer,(patch->>'late_reg_mins')::integer,(patch->>'rebuy_chips')::integer,(patch->>'rebuy_levels')::integer,(patch->>'addon_chips')::integer,(patch->>'addon_levels')::integer,(patch->>'addon_from_start')::boolean,COALESCE((patch->>'addon_break_minutes')::integer,t.addon_break_minutes),(patch->>'big_blind_ante')::boolean);
    GET DIAGNOSTICS changed = ROW_COUNT;
    RAISE NOTICE 'Midway %: % unregistered future events updated',item->>'name',changed;
  END LOOP;
END;
$midway$;
COMMIT;
